function _loadDNA(){ try{ const d=load('amv_dna'); if(d&&d.colors) return Object.assign(JSON.parse(JSON.stringify(DNA_DEFAULT)), d); }catch(e){} return JSON.parse(JSON.stringify(DNA_DEFAULT)); }
